import{_ as o,o as t,c as s,a2 as a}from"./chunks/framework.Boholvbs.js";const i="/docs/assets/stories-near-you-block.ssQFuC3V.png",r="/docs/assets/stories-near-you-settings.CZ4YVEHU.png",n="/docs/assets/stories-near-you-block2.D_2mBtfK.png",m=JSON.parse('{"title":"Stories Near You","description":"","frontmatter":{},"headers":[],"relativePath":"stories-near-you.md","filePath":"stories-near-you.md"}'),l={name:"stories-near-you.md"};function c(h,e,u,d,g,p){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="stories-near-you" tabindex="-1">Stories Near You <a class="header-anchor" href="#stories-near-you" aria-label="Permalink to &quot;Stories Near You&quot;">​</a></h1><p>The <strong>Stories Near You</strong> block (<code>jeo/stories-near-you</code>) displays geolocated posts that are closest to the reader&#39;s current location. It uses the browser&#39;s geolocation API (with explicit user consent) to find nearby stories and presents them in a customizable card layout.</p><p><img src="'+i+'" alt="Stories Near You block"></p><h2 id="inserting-the-block" tabindex="-1">Inserting the block <a class="header-anchor" href="#inserting-the-block" aria-label="Permalink to &quot;Inserting the block&quot;">​</a></h2><ol><li>In the Gutenberg editor, click the <strong>+</strong> button to add a new block.</li><li>Search for <strong>Stories Near You</strong> and select it.</li><li>Configure the block settings in the Inspector panels.</li></ol><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>When a visitor loads a page with this block:</p><ol><li>The block shows a <strong>consent prompt</strong>: &quot;Use my location&quot; or &quot;Skip&quot;.</li><li>If the user consents, the browser obtains their coordinates (rounded for privacy based on the <strong>geolocation precision</strong> setting).</li><li>If the user skips, the block falls back to the default map center configured in JEO Settings.</li><li>The block queries the WordPress database for the closest geolocated posts using geographic distance (<code>ST_Distance_Sphere</code>).</li><li>Posts are rendered as cards in the chosen layout.</li></ol><h3 id="geolocation-precision" tabindex="-1">Geolocation precision <a class="header-anchor" href="#geolocation-precision" aria-label="Permalink to &quot;Geolocation precision&quot;">​</a></h3><p>The <strong>User location precision</strong> setting (in JEO → Settings → General) controls how many decimal places are kept from the browser geolocation. Range: 1–5, default: 2. Lower values mean less precision but more privacy.</p><p><img src="'+r+'" alt="Stories Near You settings"></p><h2 id="block-settings" tabindex="-1">Block settings <a class="header-anchor" href="#block-settings" aria-label="Permalink to &quot;Block settings&quot;">​</a></h2><p>The Inspector panels provide extensive customization:</p><h3 id="post-card" tabindex="-1">Post Card <a class="header-anchor" href="#post-card" aria-label="Permalink to &quot;Post Card&quot;">​</a></h3><ul><li><strong>Layout</strong>: Grid or List.</li><li><strong>Media position</strong>: Top, Left, Right, or Behind (the image is placed behind the text).</li><li><strong>Image shape</strong>: Landscape, Portrait, Square, or Uncropped.</li><li><strong>Columns</strong>: Number of columns in grid layout (1–6).</li></ul><h3 id="query-settings" tabindex="-1">Query Settings <a class="header-anchor" href="#query-settings" aria-label="Permalink to &quot;Query Settings&quot;">​</a></h3><ul><li><strong>Posts per page</strong>: Total posts to display (max 36).</li><li><strong>Post type</strong>: Filter by post type (only shown if multiple geo-enabled types exist).</li></ul><h3 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h3><ul><li><strong>Categories</strong>: Include specific categories.</li><li><strong>Tags</strong>: Include specific tags.</li><li><strong>Category exclusions</strong>: Exclude specific categories.</li><li><strong>Tag exclusions</strong>: Exclude specific tags.</li><li><strong>Custom taxonomies</strong>: Filter by custom taxonomy terms.</li></ul><h3 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to &quot;Display&quot;">​</a></h3><ul><li><strong>Thumbnail</strong>: Show/hide featured image.</li><li><strong>Category</strong>: Show/hide category badge.</li><li><strong>Date</strong>: Show/hide publication date.</li><li><strong>Excerpt</strong>: Show/hide excerpt (with configurable word count).</li><li><strong>Author</strong>: Show/hide author name.</li><li><strong>Author avatar</strong>: Show/hide author photo (requires Author enabled).</li><li><strong>Read more</strong>: Show/hide &quot;Read more&quot; link (with custom label).</li></ul><h3 id="typography-spacing" tabindex="-1">Typography &amp; Spacing <a class="header-anchor" href="#typography-spacing" aria-label="Permalink to &quot;Typography &amp; Spacing&quot;">​</a></h3><ul><li><strong>Type scale</strong>: Font size scale (1–10).</li><li><strong>Image scale</strong>: Image width in horizontal layouts (1–4).</li><li><strong>Column gap</strong>: Spacing between columns (small, medium, large).</li><li><strong>Min height</strong>: Minimum height for &quot;Behind&quot; layout.</li></ul><h3 id="colors" tabindex="-1">Colors <a class="header-anchor" href="#colors" aria-label="Permalink to &quot;Colors&quot;">​</a></h3><p>Text and link colors use the native Gutenberg color settings (not a separate panel).</p><p><img src="'+n+'" alt="Stories Near You block"></p><h2 id="cross-block-deduplication" tabindex="-1">Cross-block deduplication <a class="header-anchor" href="#cross-block-deduplication" aria-label="Permalink to &quot;Cross-block deduplication&quot;">​</a></h2><p>When multiple Stories Near You blocks are on the same page, posts are <strong>never repeated</strong> across blocks. The first block shows the closest posts, the second block shows the next closest (excluding the first block&#39;s posts), and so on.</p><p>This works both in the editor preview and on the frontend.</p><h2 id="newspack-compatibility" tabindex="-1">Newspack compatibility <a class="header-anchor" href="#newspack-compatibility" aria-label="Permalink to &quot;Newspack compatibility&quot;">​</a></h2><p>If the <a href="https://newspack.pub/" target="_blank" rel="noreferrer">Newspack Blocks</a> plugin is active, the block automatically uses Newspack&#39;s card templates and styles for a seamless visual integration with your Newspack theme.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Posts must be geolocated (have <code>_related_point</code> meta data). See <a href="./geolocating-posts">Geolocating posts</a>.</li><li>The JEO default map center must be configured in <strong>Jeo → Settings</strong> (used as fallback when the user does not share their location).</li></ul>',33)])])}const k=o(l,[["render",c]]);export{m as __pageData,k as default};
